using FreeSql; using VelrixWorkHub.Domain;
namespace VelrixWorkHub.Infrastructure.SalesOrders;
public static class SalesOrderSeedData { public static void Initialize(IFreeSql fsql) { fsql.CodeFirst.SyncStructure<SalesOrderRecord>(); if (fsql.Select<SalesOrderRecord>().Any()) return; var customer=fsql.Select<VelrixWorkHub.Infrastructure.Customers.CustomerRecord>().First(); var product=fsql.Select<VelrixWorkHub.Infrastructure.Products.ProductRecord>().First(); var project=fsql.Select<VelrixWorkHub.Infrastructure.PmpProjects.PmpProjectRecord>().First(); if(customer is null||product is null)return; var x=new SalesOrder("SO-20260712-001",customer.Id,product.Id,DateOnly.FromDateTime(DateTime.Today),3,1680,null,project?.Id); fsql.Insert(new SalesOrderRecord{Id=x.Id,OrderNo=x.OrderNo,CustomerId=x.CustomerId,ProductId=x.ProductId,PmpProjectId=x.PmpProjectId,OrderDate=x.OrderDate.ToDateTime(TimeOnly.MinValue),DueDate=x.DueDate.ToDateTime(TimeOnly.MinValue),Quantity=x.Quantity,UnitPrice=x.UnitPrice,Status=x.Status}).ExecuteAffrows(); } }
